        'clients' => [
            'create' => 'CREATE TABLE `clients` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT \'ID intero autoincrementante\',
  `company_id` bigint unsigned DEFAULT NULL COMMENT \'Azienda (tenant) proprietaria del record\',
  `is_person` tinyint(1) NOT NULL DEFAULT \'1\' COMMENT \'Persona fisica (true) o giuridica (false)\',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT \'Cognome (se persona fisica) o Ragione Sociale (se giuridica)\',
  `first_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Nome persona fisica\',
  `tax_code` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Codice Fiscale o Partita IVA del cliente\',
  `vat_number` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Partita IVA\',
  `email` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Email di contatto principale\',
  `phone` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Recapito telefonico\',
  `iban` varchar(34) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'IBAN del cliente (in chiaro)\',
  `employer_id` bigint unsigned DEFAULT NULL COMMENT \'Datore di lavoro (self-reference su clients.id)\',
  `website` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Sito web del cliente\',
  `is_pep` tinyint(1) NOT NULL DEFAULT \'0\' COMMENT \'Persona Politicamente Esposta\',
  `client_type_id` bigint unsigned DEFAULT NULL COMMENT \'Classificazione cliente\',
  `is_sanctioned` tinyint(1) NOT NULL DEFAULT \'0\' COMMENT \'Presente in liste antiterrorismo/blacklists\',
  `is_remote_interaction` tinyint(1) NOT NULL DEFAULT \'0\' COMMENT \'Operatività a distanza = Rischio più alto\',
  `general_consent_at` timestamp NULL DEFAULT NULL COMMENT \'Consenso generale al trattamento base\',
  `privacy_policy_read_at` timestamp NULL DEFAULT NULL COMMENT \'Data presa visione informativa Art.13\',
  `consent_special_categories_at` timestamp NULL DEFAULT NULL COMMENT \'Consenso dati sanitari/giudiziari per polizze/CQS\',
  `consent_sic_at` timestamp NULL DEFAULT NULL COMMENT \'Consenso interrogazione CRIF/CTC/Experian\',
  `consent_marketing_at` timestamp NULL DEFAULT NULL COMMENT \'Consenso comunicazioni commerciali e newsletter\',
  `consent_profiling_at` timestamp NULL DEFAULT NULL COMMENT \'Consenso profilazione abitudini di consumo/spesa\',
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT \'raccolta_dati\' COMMENT \'raccolta_dati, valutazione_aml, approvata, sos_inviata, chiusa\',
  `is_company` tinyint(1) NOT NULL DEFAULT \'0\' COMMENT \'True se il cliente è un\'\'azienda fornitore\',
  `is_lead` tinyint(1) NOT NULL DEFAULT \'0\' COMMENT \'True se è un lead non ancora convertito\',
  `leadsource_id` bigint unsigned DEFAULT NULL COMMENT \'ID del client che ha fornito il lead\',
  `acquired_at` timestamp NULL DEFAULT NULL COMMENT \'Data di acquisizione del contatto\',
  `contoCOGE` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Conto COGE\',
  `privacy_consent` tinyint(1) NOT NULL DEFAULT \'0\' COMMENT \'Consenso privacy del cliente\',
  `is_client` tinyint(1) NOT NULL DEFAULT \'1\' COMMENT \'contraente contratto\',
  `subfornitori` text COLLATE utf8mb4_unicode_ci COMMENT \'Subfornitori da comunicare per gradimento\',
  `is_requiredApprovation` tinyint(1) NOT NULL DEFAULT \'0\' COMMENT \'Da far approvare per gradimento\',
  `is_approved` tinyint(1) NOT NULL DEFAULT \'1\' COMMENT \'Approvata per gradimento\',
  `is_anonymous` tinyint(1) NOT NULL DEFAULT \'0\' COMMENT \'Cliente anonimo (non comunicabile)\',
  `blacklist_at` timestamp NULL DEFAULT NULL COMMENT \'Data inserimento in blacklist\',
  `blacklisted_by` bigint unsigned DEFAULT NULL COMMENT \'ID dell\'\'utente che ha inserito in blacklist (senza link esterni)\',
  `salary` decimal(10,2) DEFAULT NULL COMMENT \'Retribuzione annuale del cliente\',
  `salary_quote` decimal(10,2) DEFAULT NULL COMMENT \'Quota retribuzione per calcoli finanziari\',
  `is_art108` tinyint(1) NOT NULL DEFAULT \'0\' COMMENT \'Esente art. 108 - ex art. 128-novies TUB\',
  `is_consultant_gdpr` tinyint(1) NOT NULL DEFAULT \'0\' COMMENT \'Consulente ai fini GDPR\',
  `privacy_contact_email` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Email contatto privacy\',
  `dpo_email` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Email DPO\',
  `is_iso27001_certified` tinyint(1) NOT NULL DEFAULT \'0\' COMMENT \'Certificazione ISO 27001\',
  `is_dummy` tinyint(1) NOT NULL DEFAULT \'0\' COMMENT \'Record fittizio, usato per test o dimostrazioni\',
  `employee_roles` json DEFAULT NULL COMMENT \'Ruoli (nomi EmployeeType) associati a questo client (consulente esterno o cliente finale), stessa struttura di employees.employee_roles\',
  `user_id` bigint unsigned DEFAULT NULL COMMENT \'ID dell\'\'utente collegato (account di login)\',
  `birth_date` date DEFAULT NULL COMMENT \'Data di nascita\',
  `birth_place` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Luogo di nascita (comune e provincia)\',
  `sex` char(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'M | F\',
  `citizenship` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Cittadinanza\',
  `legal_representative_id` bigint unsigned DEFAULT NULL COMMENT \'Legale rappresentante / amministratore (self-reference su clients.id)\',
  `pec` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Indirizzo PEC (posta elettronica certificata) della societa\',
  `ateco_code` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Codice Ateco dell\'\'attivita prevalente della societa\',
  `cciaa_registration` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Iscrizione alla Camera di Commercio (CCIAA / numero REA)\',
  `legal_form` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Forma giuridica (registro imprese)\',
  `sdi_code` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Codice destinatario SDI\',
  `activity_status` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Stato attivita (es. ATTIVA)\',
  `company_started_at` date DEFAULT NULL COMMENT \'Data inizio attivita\',
  `share_capital` decimal(16,2) DEFAULT NULL COMMENT \'Capitale sociale\',
  `employees` int unsigned DEFAULT NULL COMMENT \'Numero dipendenti (ultimo dato disponibile)\',
  `turnover` decimal(16,2) DEFAULT NULL COMMENT \'Fatturato ultimo bilancio\',
  `net_worth` decimal(16,2) DEFAULT NULL COMMENT \'Patrimonio netto ultimo bilancio\',
  `balance_year` smallint unsigned DEFAULT NULL COMMENT \'Anno ultimo bilancio\',
  `registry_updated_at` timestamp NULL DEFAULT NULL COMMENT \'Ultimo aggiornamento dei dati dal registro imprese\',
  `created_at` timestamp NULL DEFAULT NULL COMMENT \'Data acquisizione cliente\',
  `updated_at` timestamp NULL DEFAULT NULL COMMENT \'Ultima modifica anagrafica\',
  PRIMARY KEY (`id`),
  KEY `clients_blacklist_at_index` (`blacklist_at`),
  KEY `clients_is_anonymous_index` (`is_anonymous`),
  KEY `clients_is_approved_index` (`is_approved`),
  KEY `clients_company_id_foreign` (`company_id`),
  KEY `clients_employer_id_foreign` (`employer_id`),
  KEY `clients_client_type_id_foreign` (`client_type_id`),
  KEY `clients_blacklisted_by_foreign` (`blacklisted_by`),
  KEY `clients_user_id_foreign` (`user_id`),
  KEY `clients_legal_representative_id_foreign` (`legal_representative_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT=\'Clienti finali: persone fisiche e giuridiche, con dati KYC e consensi privacy\'',
