            'create' => 'CREATE TABLE `documents` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT \'UUID v4 del documento\',
  `company_id` bigint unsigned DEFAULT NULL COMMENT \'ID Tenant proprietario\',
  `documentable_type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT \'Alias del modello a cui è collegato il documento (morph map)\',
  `documentable_id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT \'ID del record a cui è collegato il documento\',
  `document_type_id` bigint unsigned DEFAULT NULL COMMENT \'Tipo di documento di riferimento\',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Titolo logico o nome file del documento\',
  `training_hours` int DEFAULT NULL COMMENT \'Ore di formazione richieste\',
  `training_organization` enum(\'interna\',\'OAM\',\'IVASS\',\'PRIVACY\') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Formazione per organizzazione\',
  `docnumber` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Numero protocollo o identificativo del documento\',
  `spatie_collection` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT \'default\' COMMENT \'Nome della collection per Spatie Media Library\',
  `document_url` varchar(2048) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'URL pubblico o percorso del documento sul web/storage\',
  `status` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT \'caricato\' COMMENT \'Valori di DocumentStatus: na, richiesto, caricato, approvato, respinto, provvisorio, scaduto, illegibile, revocato\',
  `last_sent_at` timestamp NULL DEFAULT NULL COMMENT \'Data e ora ultimo sollecito inviato\',
  `reminders_count` int unsigned NOT NULL DEFAULT \'0\' COMMENT \'Numero totale di solleciti inviati\',
  `sync_status` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT \'local\' COMMENT \'Stato sincronizzazione cloud: local, syncing, synced, failed\',
  `source_app` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT \'local\' COMMENT \'Applicazione di origine (es. local, sharepoint, google_drive)\',
  `app_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'ID univoco del file nel sistema di terze parti\',
  `app_drive_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'ID del Drive/Folder nel sistema di terze parti\',
  `app_etag` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'ETag per il controllo della versione in cloud\',
  `extracted_text` longtext COLLATE utf8mb4_unicode_ci COMMENT \'Testo grezzo estratto tramite OCR\',
  `metadata` json DEFAULT NULL COMMENT \'Dati chiave estratti in formato JSON\',
  `ai_abstract` text COLLATE utf8mb4_unicode_ci COMMENT \'Riassunto testuale generato dall\'\'Intelligenza Artificiale\',
  `ai_confidence_score` tinyint unsigned DEFAULT NULL COMMENT \'Punteggio di affidabilita AI (0-100)\',
  `is_monitored` tinyint(1) NOT NULL DEFAULT \'0\' COMMENT \'Scadenza monitorata nel tempo\',
  `is_template` tinyint(1) NOT NULL DEFAULT \'0\' COMMENT \'Indica se è un modello vuoto fornito dall\'\'azienda\',
  `doctype` enum(\'modulo\',\'informativa\',\'procedura\',\'template\') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Tipo documento: modulo, procedura, template\',
  `cellposition` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Posizione della cella in cui si trova il documento\',
  `is_signed` tinyint(1) NOT NULL DEFAULT \'0\' COMMENT \'Indica se il documento è stato firmato\',
  `is_unique` tinyint(1) NOT NULL DEFAULT \'0\' COMMENT \'Se true, è l\'\'unico documento ammesso in questa collection\',
  `is_end_month` tinyint(1) NOT NULL DEFAULT \'0\' COMMENT \'Approssima la scadenza all\'\'ultimo giorno del mese\',
  `emitted_by` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Ente di rilascio\',
  `emitted_at` date DEFAULT NULL COMMENT \'Data di emissione del documento\',
  `expires_at` date DEFAULT NULL COMMENT \'Data di scadenza del documento\',
  `delivered_at` timestamp NULL DEFAULT NULL COMMENT \'Data di consegna fisica o digitale\',
  `signed_at` timestamp NULL DEFAULT NULL COMMENT \'Data e ora della firma\',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT \'Descrizione pubblica visibile all\'\'utente\',
  `internal_notes` text COLLATE utf8mb4_unicode_ci COMMENT \'Note interne visibili solo agli amministratori\',
  `rejection_note` text COLLATE utf8mb4_unicode_ci COMMENT \'Motivazione in caso di rifiuto del documento\',
  `user_id` bigint unsigned DEFAULT NULL COMMENT \'FK Utente o Cliente intestatario\',
  `renewed_by` bigint unsigned DEFAULT NULL COMMENT \'FK Utente che ha aggiornato il documento\',
  `replaced_by_id` bigint unsigned DEFAULT NULL COMMENT \'Documento che sostituisce questo (es. versione firmata)\',
  `uploaded_by` bigint unsigned DEFAULT NULL COMMENT \'FK Utente che ha eseguito l\'\'upload\',
  `verified_by` bigint unsigned DEFAULT NULL COMMENT \'FK Admin che ha verificato e approvato\',
  `verified_at` timestamp NULL DEFAULT NULL COMMENT \'Data e ora di verifica\',
  `created_by` bigint unsigned DEFAULT NULL COMMENT \'FK Utente creatore del record\',
  `updated_by` bigint unsigned DEFAULT NULL COMMENT \'FK Utente che ha aggiornato il record\',
  `deleted_by` bigint unsigned DEFAULT NULL COMMENT \'FK Utente che ha eliminato il record\',
  `file_hash` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Hash SHA-256 del file per prevenire duplicati esatti\',
  `channel` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Canale di arrivo: upload, email, whatsapp, drive, sharepoint, generated, signature\',
  `channel_ref` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Riferimento nel canale (Message-Id, media id WhatsApp, id busta di firma)\',
  `created_at` timestamp NULL DEFAULT NULL COMMENT \'Data e ora di creazione del record\',
  `updated_at` timestamp NULL DEFAULT NULL COMMENT \'Data e ora dell\'\'ultima modifica del record\',
  `deleted_at` timestamp NULL DEFAULT NULL COMMENT \'Data e ora di eliminazione logica (soft delete); nullo = record attivo\',
  PRIMARY KEY (`id`),
  KEY `documents_documentable_type_documentable_id_index` (`documentable_type`,`documentable_id`),
  KEY `doc_expires_at_index` (`expires_at`),
  KEY `doc_status_index` (`status`),
  KEY `documents_file_hash_index` (`file_hash`),
  KEY `documents_company_id_foreign` (`company_id`),
  KEY `documents_document_type_id_foreign` (`document_type_id`),
  KEY `documents_user_id_foreign` (`user_id`),
  KEY `documents_renewed_by_foreign` (`renewed_by`),
  KEY `documents_replaced_by_id_foreign` (`replaced_by_id`),
  KEY `documents_uploaded_by_foreign` (`uploaded_by`),
  KEY `documents_verified_by_foreign` (`verified_by`),
  KEY `documents_created_by_foreign` (`created_by`),
  KEY `documents_updated_by_foreign` (`updated_by`),
  KEY `documents_deleted_by_foreign` (`deleted_by`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT=\'Archivio centralizzato dei documenti, allegati e file con supporto OCR e AI\'',
