  `comune` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Comune di residenza\',
  `cap` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Codice di avviamento postale\',
