  `piva` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Partita IVA\',
  `cf` char(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Codice fiscale\',
